using namespace ark;using V=arkjson::Value;
void check(bool condition,const char* message){if(!condition)throw std::runtime_error(message);}
void close(double a,double b,double tolerance,const char* message){if(std::abs(a-b)>tolerance)throw std::runtime_error(std::string(message)+": "+std::to_string(a)+" != "+std::to_string(b));}
V parse(const char* text){V v;if(!arkjson::parse(text,v))throw std::runtime_error("Invalid test JSON");return v;}
V accepted(V r){if(r.find("isError")->b)throw std::runtime_error(r.find("structuredContent")->dump());return *r.find("structuredContent");}
V call(AgentSession& s,const char* tool,const char* args){return accepted(s.call(tool,parse(args)));}
void environment(const char* name,const char* value){
#ifdef _WIN32
_putenv_s(name,value);
#else
if(*value)setenv(name,value,1);else unsetenv(name);
#endif
}
struct Environment {const char* name;std::string old;Environment(const char* n,const char* value):name(n),old(std::getenv(n)?std::getenv(n):""){environment(name,value);}~Environment(){environment(name,old.c_str());}};
void transactions(){
    AgentSession s;call(s,"doc_apply",R"({"commands":[{"op":"param.set","name":"width","expr":10},{"op":"feature.add","type":"box","name":"Block","p":{"dx":"width","dy":10,"dz":10}}]})");
    const auto initial=documentToJson(s.document);auto rejected=s.call("doc_apply",parse(R"({"expected_revision":1,"commands":[{"op":"param.set","name":"width","expr":12}],"checks":[{"id":"minimum_width","query":{"tool":"eval_expr","args":{"expr":"width*2"},"path":"value"},"op":"ge","value":30,"parameters":["width"],"diagnose":true}]})"));
    check(rejected.find("isError")->b,"failed condition rejects batch");const auto& failure=*rejected.find("structuredContent");check(failure.find("error_code")->str=="POSTCONDITION_FAILED","typed postcondition failure");const auto& row=failure.find("conditions")->find("checks")->arr[0];close(row.find("observed")->num,24,0,"observed value");close(row.find("required_delta")->num,6,0,"required correction");close(row.find("sensitivities")->arr[0].find("derivative")->num,2,1e-8,"measured sensitivity");check(initial==documentToJson(s.document)&&s.revision==1,"postcondition rollback preserves document and revision");
    auto preview=call(s,"doc_preview",R"({"expected_revision":1,"commands":[{"op":"param.set","name":"width","expr":16}],"checks":[{"query":{"tool":"eval_expr","args":{"expr":"width"},"path":"value"},"op":"between","min":15,"max":20}]})");check(preview.find("valid")->b&&preview.find("candidate_cached")->b,"candidate cached");check(documentToJson(s.document)==initial,"prepare is read only");auto committed=accepted(s.call("doc_apply",*preview.find("apply")));check(committed.find("applied_prepared")->b&&!committed.find("geometry_recomputed")->b,"commit reuses geometry");close(s.document.getParam("width"),16,0,"prepared model applied");check(s.call("doc_apply",*preview.find("apply")).find("isError")->b,"candidate cannot be replayed");call(s,"doc_undo",R"({})");check(documentToJson(s.document)==initial,"prepared commit is one undo entry");
    auto guarded=call(s,"doc_preview",R"({"expected_revision":3,"commands":[{"op":"param.set","name":"width","expr":15}]})");V tampered=*guarded.find("apply");tampered.set("commands",parse(R"([{"op":"param.set","name":"width","expr":100}])"));check(s.call("doc_apply",tampered).find("isError")->b&&documentToJson(s.document)==initial,"prepared commands cannot be overridden");
    auto stale=call(s,"doc_preview",R"({"expected_revision":3,"commands":[{"op":"param.set","name":"width","expr":18}]})");call(s,"doc_apply",R"({"commands":[{"op":"param.set","name":"width","expr":11}]})");check(s.call("doc_apply",*stale.find("apply")).find("isError")->b,"changed revision rejects candidate");
    V args=parse(R"({"expected_revision":4,"commands":[{"op":"param.set","name":"width","expr":15}]})");auto cached=accepted(s.call("doc_preview",args));s.document.setParam("width","13");check(s.call("doc_apply",*cached.find("apply")).find("isError")->b,"same-revision direct edit rejects candidate fingerprint");
    AgentSession other;other.document=s.document;other.revision=s.revision;check(other.call("doc_apply",*cached.find("apply")).find("isError")->b,"candidate has session custody");
    call(s,"doc_apply",R"({"commands":[{"op":"material.set","name":"Test","density_kg_m3":2700,"physical":{"young_modulus_Pa":70000000000,"poisson_ratio":0.33}}]})");auto materials=call(s,"materials_inspect",R"({})");close(materials.find("materials")->arr[0].find("density_g_cm3")->num,2.7,1e-12,"density unit conversion");V serialized;arkjson::parse(documentToJson(s.document),serialized);check(serialized.find("version")->num==20,"elastic materials version");Document restored;std::string error;check(documentFromJson(serialized.dump(),restored,&error),"elastic material roundtrip");close(restored.materials[0].physical.find("young_modulus_Pa")->num,70e9,0,"elastic modulus persists");
    const auto before=documentToJson(s.document);check(s.call("doc_apply",parse(R"({"commands":[{"op":"material.set","name":"Test","physical":{"poisson_ratio":0.5}}]})")).find("isError")->b,"incompressible singular elastic declaration rejected");check(before==documentToJson(s.document),"bad material atomic");
}
void nestedThreads(){
    std::atomic<int> sum{0};parallel_for(0,128,[&](i64 a,i64 b){for(i64 i=a;i<b;++i)parallel_for(0,128,[&](i64 x,i64 y){sum+=(int)(y-x);});});check(sum==16384,"nested parallel loop terminates and preserves work");bool threw=false;try{parallel_for(0,128,[](i64 a,i64){if(a==0)throw std::runtime_error("expected");});}catch(const std::exception&){threw=true;}check(threw,"parallel exceptions reach the caller");
    Document doc;Feature box;box.type=FeatureType::Box;doc.addFeature(box);{Environment invalid("ARK_FEATURE_THREADS","invalid");bool rejected=false;try{doc.recompute();}catch(const std::exception&){rejected=true;}check(rejected&&doc.evaluatingBodies==nullptr,"invalid scheduler configuration releases evaluation custody");}doc.recompute();check(doc.lastResults.front().ok,"evaluation recovers after bad configuration");
}
